523	\begin{definition}[State space of a linear register]\label{def:lin-reg}
524		\uses{def:complementary}
525		For a set $V$, we write $\C^V$ for the complex vector space of dimension
526		$|V|$, endowed with the canonical orthonormal basis
527		$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
528		$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
529		subspaces over $\F$, then $\C^V$ is identified with
530		$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
531		$\ket{x_1 \oplus \dots \oplus x_k}$ with
532		$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
533		$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
534		$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
535		the \emph{qudits} of $\C^V$.
536	\end{definition}
537	
538	\begin{definition}[EPR state]\label{def:EPR}
539		\uses{def:lin-reg}
540		For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
541		$\C^V \ot \C^V$ is
542		\[
543			\ket{\mathrm{EPR}}_V
544			= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
545		\]
546		We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
547		$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
548	\end{definition}
