600	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
601		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
602		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
603		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
604		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
605		\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
